using System;
using System.Linq;

namespace Catan.Core.ThreeKingdoms
{
    public sealed class SkillDefinition
    {
        public string Id { get; }
        public string Name { get; }
        public string OriginalText { get; }
        public bool Enabled => GeneralCatalog.IsEnabled(Id.Substring(0, 6));
        internal SkillDefinition(string id, string name, string text) { Id=id; Name=name; OriginalText=text; }
    }
    public sealed class GeneralDefinition
    {
        public string Id { get; }
        public string Name { get; }
        public string Title { get; }
        public string Faction { get; }
        public string OriginalText { get; }
        public string SourceHash { get; }
        public string SourceReference => "docs/三国争霸游戏百科.md：武将" + Id.Substring(4);
        public bool SkillsEnabled => GeneralCatalog.IsEnabled(Id);
        private readonly SkillDefinition[] skills;
        public SkillDefinition[] Skills => (SkillDefinition[])skills.Clone();
        internal GeneralDefinition(string id,string name,string title,string faction,string text,string hash,SkillDefinition[] values)
        { Id=id; Name=name; Title=title; Faction=faction; OriginalText=text; SourceHash=hash; skills=values; }
    }
    // 来源：B0 原始资料指纹与百科原文；保留 B1/B2 身份，B3 以完整启用名单和独立哈希管理。
