        private static readonly GeneralDefinition[] items = new[]
        {
            new GeneralDefinition("tk-g01","张辽","登锋陷阵","魏","### 01．张辽｜登锋陷阵（魏）\n\n**突袭**\n\n任意回合的摸牌阶段开始时，你可以少摸x张牌并获得x名玩家各一张手牌。（x不能大于本回合的摸牌数）","b0e7234fbc3b98c04073176b973d837d5230c84996898d1e9461ff93f99a7971",new[] { new SkillDefinition("tk-g01-s1","突袭","任意回合的摸牌阶段开始时，你可以少摸x张牌并获得x名玩家各一张手牌。（x不能大于本回合的摸牌数）") }),
            new GeneralDefinition("tk-g02","吕布","傲睨万物","群","### 02．吕布｜傲睨万物（群）\n\n**无双**\n\n登场时，你立即获得一个可用的等级最低的骑士（激活状态），你的骑士等级视为+1级。你的骑士激活后可以立即行动。\n\n**利驭**\n\n任意玩家可以给你等同于某个骑士等级数量的小麦（若为你则改为弃置同等数量的小麦），将该骑士移至任意道路上然后可以驱赶强盗或击杀其他玩家的骑士（不包括你的），每回合不限次数。当吕布隐退后，骑士需任意放置在你的道路上。","29988187d7028ecf7a4be1077dff5b154f2ae8482db4bf8cc9c4499f76729b58",new[] { new SkillDefinition("tk-g02-s1","无双","登场时，你立即获得一个可用的等级最低的骑士（激活状态），你的骑士等级视为+1级。你的骑士激活后可以立即行动。"),new SkillDefinition("tk-g02-s2","利驭","任意玩家可以给你等同于某个骑士等级数量的小麦（若为你则改为弃置同等数量的小麦），将该骑士移至任意道路上然后可以驱赶强盗或击杀其他玩家的骑士（不包括你的），每回合不限次数。当吕布隐退后，骑士需任意放置在你的道路上。") }),
            new GeneralDefinition("tk-g03","周瑜","雄姿英发","吴","### 03．周瑜｜雄姿英发（吴）\n\n**英姿**\n\n摸牌阶段，你多摸一张任意资源牌（商品牌）和一张随机资源牌。\n\n**反间**\n\n出牌阶段限一次，你可以令一名玩家选择一种资源/商品，然后该玩家获得你的一张手牌并展示之，若不同，则你拆除/横置对方一条道路。","fd3803c0bb5f565d1e230eff9483ce41bf392a597be0c7486bd7b714752b4790",new[] { new SkillDefinition("tk-g03-s1","英姿","摸牌阶段，你多摸一张任意资源牌（商品牌）和一张随机资源牌。"),new SkillDefinition("tk-g03-s2","反间","出牌阶段限一次，你可以令一名玩家选择一种资源/商品，然后该玩家获得你的一张手牌并展示之，若不同，则你拆除/横置对方一条道路。") }),
            new GeneralDefinition("tk-g04","貂蝉","舞惑群心","群","### 04．貂蝉｜舞惑群心（群）\n\n**惑心**\n\n限定技，在任意玩家的回合开始之前，你可以代替其操控整个回合，本回合你跟其他玩家不能进行大于1：1的交易。\n\n**闭月**\n\n你的回合结束时摸两张任意资源牌。","b9b14765bf91638688d4007ce516fd3c16647a97d712b02f4f8fed2ef56aeff1",new[] { new SkillDefinition("tk-g04-s1","惑心","限定技，在任意玩家的回合开始之前，你可以代替其操控整个回合，本回合你跟其他玩家不能进行大于1：1的交易。"),new SkillDefinition("tk-g04-s2","闭月","你的回合结束时摸两张任意资源牌。") }),
            new GeneralDefinition("tk-g05","大乔","衣垂绿川","吴","### 05．大乔｜衣垂绿川（吴）\n\n**流离**\n\n出牌阶段限一次，你可以使用一张麦子移动强盗/海盗。\n\n**国色**\n\n出牌阶段限一次，你可以弃置两张砖对一名玩家使用乐不思蜀。\n乐不思蜀：在你的回合开始前投掷一次骰子，若点数不大于7，则出牌阶段你不能失去手牌/发展牌。","0f8f9249606892ea88bd5b2037da98efd81cc94f249f3d4460e174308d633b7b",new[] { new SkillDefinition("tk-g05-s1","流离","出牌阶段限一次，你可以使用一张麦子移动强盗/海盗。"),new SkillDefinition("tk-g05-s2","国色","出牌阶段限一次，你可以弃置两张砖对一名玩家使用乐不思蜀。\n乐不思蜀：在你的回合开始前投掷一次骰子，若点数不大于7，则出牌阶段你不能失去手牌/发展牌。") }),
            new GeneralDefinition("tk-g06","曹仁","国之柱石","魏","### 06．曹仁｜国之柱石（魏）\n\n**据守**\n\n回合结束时，你可以摸四张任意资源牌，然后在其他玩家回合内，你不能摸牌直至你的回合开始。","3e58b4dbdf84eb903f05afb5224b3393b3947ef2833d69ff8ffadc1b74c636bb",new[] { new SkillDefinition("tk-g06-s1","据守","回合结束时，你可以摸四张任意资源牌，然后在其他玩家回合内，你不能摸牌直至你的回合开始。") }),
            new GeneralDefinition("tk-g07","于吉","神术妙法","群","### 07．于吉｜神术妙法（群）\n\n**蛊惑**\n\n在任意时机，当你需要使用或交易资源牌/商品牌时，你可以选择一张手牌并声明一种资源/商品，令其他玩家质疑真假。若猜测正确，该玩家获得一张随机资源牌，且你弃置该手牌；若猜测错误，你弃置其一张手牌。若无玩家质疑或所有玩家均质疑失败，则该牌按你所述之牌结算。","c4c1329eca79b92c8d9ba9f1d9cc0ce9e2ed57acd62951bf4c718bb8273217e7",new[] { new SkillDefinition("tk-g07-s1","蛊惑","在任意时机，当你需要使用或交易资源牌/商品牌时，你可以选择一张手牌并声明一种资源/商品，令其他玩家质疑真假。若猜测正确，该玩家获得一张随机资源牌，且你弃置该手牌；若猜测错误，你弃置其一张手牌。若无玩家质疑或所有玩家均质疑失败，则该牌按你所述之牌结算。") }),
            new GeneralDefinition("tk-g08","甘宁","万人辟易","神","### 08．甘宁｜万人辟易（神）\n\n**劫营**\n\n回合结束时，你可以选择一名玩家，在该玩家出牌阶段，其摸一张任意资源牌，然后不能建设村庄，回合结束时你获得其所有手牌。\n\n**魄袭**\n\n出牌阶段限一次，你可以查看一名玩家的手牌，然后弃置你与其共4张不同的牌。根据你弃置自己牌的数量执行以下效果：0张，本局游戏你的手牌上限-1；1张，立即结束回合；3张，摸一张任意资源牌/商品牌；4张，你收获一次资源（点数为本回合投掷点数）。","13fd417f22efc30d1a443fa812b3159d3987dbdb7008410e86cf186ac47b7e6c",new[] { new SkillDefinition("tk-g08-s1","劫营","回合结束时，你可以选择一名玩家，在该玩家出牌阶段，其摸一张任意资源牌，然后不能建设村庄，回合结束时你获得其所有手牌。"),new SkillDefinition("tk-g08-s2","魄袭","出牌阶段限一次，你可以查看一名玩家的手牌，然后弃置你与其共4张不同的牌。根据你弃置自己牌的数量执行以下效果：0张，本局游戏你的手牌上限-1；1张，立即结束回合；3张，摸一张任意资源牌/商品牌；4张，你收获一次资源（点数为本回合投掷点数）。") }),
            new GeneralDefinition("tk-g09","郝昭","死守陈仓","魏","### 09．郝昭｜死守陈仓（魏）\n\n**镇骨**\n\n回合结束时，你可以选择一名其他玩家，你的回合结束时和该玩家出牌阶段开始前，你摸随机资源牌直至你的手牌数与其相同。","0daacea678cd0fed19bd7bd417d920001057871c8147af1171cb1c6ff66f91aa",new[] { new SkillDefinition("tk-g09-s1","镇骨","回合结束时，你可以选择一名其他玩家，你的回合结束时和该玩家出牌阶段开始前，你摸随机资源牌直至你的手牌数与其相同。") }),
            new GeneralDefinition("tk-g10","袁绍","一往无前","群","### 10．袁绍｜一往无前（群）\n\n**乱击**\n\n出牌阶段，你可以弃置两张相同的手牌视为一次虚拟海盗入侵，所有玩家可以打出一张石头来抵御海盗入侵，所有未抵御的玩家参与海盗入侵的结算，然后你摸抵御玩家数量的麦子。\n\n**血裔**\n\n锁定技，你的手牌上限+x（x为玩家数）。","07c2ad55b569e5bbef9d9f9c0af45a9a06a4ee1900cd1e15f885bf03463a2dae",new[] { new SkillDefinition("tk-g10-s1","乱击","出牌阶段，你可以弃置两张相同的手牌视为一次虚拟海盗入侵，所有玩家可以打出一张石头来抵御海盗入侵，所有未抵御的玩家参与海盗入侵的结算，然后你摸抵御玩家数量的麦子。"),new SkillDefinition("tk-g10-s2","血裔","锁定技，你的手牌上限+x（x为玩家数）。") }),
            new GeneralDefinition("tk-g11","贾诩","陈筹画策","群","### 11．贾诩｜陈筹画策（群）\n\n**帷幕**\n\n蓝色发展牌对你无效。贾诩隐退后，你仍可免疫一次蓝色发展卡。\n\n**乱武**\n\n限定技，出牌阶段，你令其他玩家依次打出两张砖头，否则失去/横置一条道路。\n\n**间书**\n\n限定技，你令两名其他玩家在他们回合的摸牌阶段开始时，声明任意数量手牌中的石头数量，令对方猜测是否正确，赢的玩家被对方弃置一张牌，输的玩家本回合不能摸牌。","c9fdde0d06c979f79b5c7256b519493b0fd6be6b59180cd3ee0c647e6e18a376",new[] { new SkillDefinition("tk-g11-s1","帷幕","蓝色发展牌对你无效。贾诩隐退后，你仍可免疫一次蓝色发展卡。"),new SkillDefinition("tk-g11-s2","乱武","限定技，出牌阶段，你令其他玩家依次打出两张砖头，否则失去/横置一条道路。"),new SkillDefinition("tk-g11-s3","间书","限定技，你令两名其他玩家在他们回合的摸牌阶段开始时，声明任意数量手牌中的石头数量，令对方猜测是否正确，赢的玩家被对方弃置一张牌，输的玩家本回合不能摸牌。") }),
            new GeneralDefinition("tk-g12","留赞","灵魂歌王","吴","### 12．留赞｜灵魂歌王（吴）\n\n**奋音**\n\n出牌阶段，当你建造的建筑与上一次不同时，你摸一张任意资源牌。","50189dc1ca43fd1615d67d86aa08e69ef97fb2f60b8cd0ec17ca74eff760e1ca",new[] { new SkillDefinition("tk-g12-s1","奋音","出牌阶段，当你建造的建筑与上一次不同时，你摸一张任意资源牌。") }),
            new GeneralDefinition("tk-g13","司马懿","佳期若梦","魏","### 13．司马懿｜佳期若梦（魏）\n\n**连破**\n\n限定技，你可以在任意玩家回合结束后插入自己一个额外回合，然后摸四张任意资源牌/商品牌。\n\n**鬼才**\n\n每当骰子被投掷后，你可以弃置一张资源牌/商品牌，将一个骰子点数改为你能产出该牌的点数，不限次数。","90586657729cabe38b5846971c61d8589b512322e6d12080fa3b62157bf94bfc",new[] { new SkillDefinition("tk-g13-s1","连破","限定技，你可以在任意玩家回合结束后插入自己一个额外回合，然后摸四张任意资源牌/商品牌。"),new SkillDefinition("tk-g13-s2","鬼才","每当骰子被投掷后，你可以弃置一张资源牌/商品牌，将一个骰子点数改为你能产出该牌的点数，不限次数。") }),
            new GeneralDefinition("tk-g14","曹操","逐鹿天下","魏","### 14．曹操｜逐鹿天下（魏）\n\n**奸雄**\n\n当其他玩家打出发展牌后，你立即获得之，至多获得四张发展牌。若为1分牌则该玩家失去该1分牌，你获得之（吾好人妻）。曹操隐退后，若你以此法获得的发展牌数量小于4，你仍可使用一次奸雄。","c19cf5fe292e96053ac1efbf0c4615f5e0c6924375c76049c79744e5834df465",new[] { new SkillDefinition("tk-g14-s1","奸雄","当其他玩家打出发展牌后，你立即获得之，至多获得四张发展牌。若为1分牌则该玩家失去该1分牌，你获得之（吾好人妻）。曹操隐退后，若你以此法获得的发展牌数量小于4，你仍可使用一次奸雄。") }),
            new GeneralDefinition("tk-g15","刘备","龙御天下","蜀","### 15．刘备｜龙御天下（蜀）\n\n**仁德**\n\n你的回合内，你可以将任意手牌给其他玩家。你每将两张手牌给其他玩家后（包括交易），你摸一张任意资源牌/商品牌。","3ab63c4efe3746baf361f7ad937f3867fcd9fcf3e908e4af37fc2522c2eceade",new[] { new SkillDefinition("tk-g15-s1","仁德","你的回合内，你可以将任意手牌给其他玩家。你每将两张手牌给其他玩家后（包括交易），你摸一张任意资源牌/商品牌。") }),
            new GeneralDefinition("tk-g16","黄盖","鏖战赤壁","吴","### 16．黄盖｜鏖战赤壁（吴）\n\n**苦肉**\n\n出牌阶段，你可以拆除自己的建筑/设施，摸x张任意资源牌/商品牌（x为该建筑/设施消耗的牌数）。","62e13d22a80bd7d114baaa65727a3b1b407c50d33bb9235dac9bf22f4edeed67",new[] { new SkillDefinition("tk-g16-s1","苦肉","出牌阶段，你可以拆除自己的建筑/设施，摸x张任意资源牌/商品牌（x为该建筑/设施消耗的牌数）。") }),
            new GeneralDefinition("tk-g17","甘宁","龙生九子","吴","### 17．甘宁｜龙生九子（吴）\n\n**奇袭**\n\n出牌阶段限三次，你可以选择一项，1.使用一张砖/两张砖弃置一名玩家的一张手牌/发展牌。2.使用x张砖拆除一名玩家的设施（x为设施等级）。","0b20e1bc89ae6816751c4af76f27bbaeb7a7d75641845f76698e96c699974e58",new[] { new SkillDefinition("tk-g17-s1","奇袭","出牌阶段限三次，你可以选择一项，1.使用一张砖/两张砖弃置一名玩家的一张手牌/发展牌。2.使用x张砖拆除一名玩家的设施（x为设施等级）。") }),
            new GeneralDefinition("tk-g18","关羽","明良千古","蜀","### 18．关羽｜明良千古（蜀）\n\n**武圣**\n\n限定技，你获得所有红色点数资源牌各一张。\n\n**单骑**\n\n限定技，本局游戏内，若你只有一个骑士，该骑士视为4级骑士。关羽隐退后放置在你面前不进入轮换将池。","a442320296afa723b16ebb421eba801a0d32f591b4a92080bdad9e8115ba6d2c",new[] { new SkillDefinition("tk-g18-s1","武圣","限定技，你获得所有红色点数资源牌各一张。"),new SkillDefinition("tk-g18-s2","单骑","限定技，本局游戏内，若你只有一个骑士，该骑士视为4级骑士。关羽隐退后放置在你面前不进入轮换将池。") }),
            new GeneralDefinition("tk-g19","诸葛亮","明良千古","蜀","### 19．诸葛亮｜明良千古（蜀）\n\n**观星**\n\n在你的掷骰阶段开始时，每种骰子你可以各掷两次，分别选择其中一种作为你的最终投掷结果。\n\n**空城**\n\n当你没有手牌时，你免疫一切负面效果。","840e1dc5c3c77d1d912a3748c77a3f765a28d5110f2f38f333e21454bad4b000",new[] { new SkillDefinition("tk-g19-s1","观星","在你的掷骰阶段开始时，每种骰子你可以各掷两次，分别选择其中一种作为你的最终投掷结果。"),new SkillDefinition("tk-g19-s2","空城","当你没有手牌时，你免疫一切负面效果。") }),
            new GeneralDefinition("tk-g20","孟获","祸崇南疆","蜀","### 20．孟获｜祸崇南疆（蜀）\n\n**祸首**\n\n限定技，在任意玩家回合开始时，你令本回合骰子点数为黑7（不投掷），且海盗直接入侵。本回合结束后，你可以移动一次强盗/海盗。\n\n**再起**\n\n海盗入侵/强盗/海盗负面效果对你无效。任意一次海盗入侵/掠地结算后，你选择满足条件的一项执行：1.若有人城市倒塌，则你可以升级一座城市。2.若有人得1分，则你失去1分。3.若有人失去资源牌/商品牌，则你摸一张任意资源牌/商品牌。4.若你的地块被掠夺，则该地块在强盗离开之前对你产出双倍资源。","da08066b471eaffcbb1f2a9399c970894738c5e1d6077c6c554ae553bc9df63d",new[] { new SkillDefinition("tk-g20-s1","祸首","限定技，在任意玩家回合开始时，你令本回合骰子点数为黑7（不投掷），且海盗直接入侵。本回合结束后，你可以移动一次强盗/海盗。"),new SkillDefinition("tk-g20-s2","再起","海盗入侵/强盗/海盗负面效果对你无效。任意一次海盗入侵/掠地结算后，你选择满足条件的一项执行：1.若有人城市倒塌，则你可以升级一座城市。2.若有人得1分，则你失去1分。3.若有人失去资源牌/商品牌，则你摸一张任意资源牌/商品牌。4.若你的地块被掠夺，则该地块在强盗离开之前对你产出双倍资源。") }),
            new GeneralDefinition("tk-g21","张昭张弘","同心协力","吴","### 21．张昭张弘｜同心协力（吴）\n\n**固症**\n\n你获得所有玩家在点数为7时弃置的手牌。\n\n**直谏**\n\n在任意玩家回合开始时，你可令本回合点数为任意颜色的7（不投掷），至多发动三次。","0daa40159c5de2b371caa4064d5f2043a043783a23b5c8be8b39b6fffd38ca7f",new[] { new SkillDefinition("tk-g21-s1","固症","你获得所有玩家在点数为7时弃置的手牌。"),new SkillDefinition("tk-g21-s2","直谏","在任意玩家回合开始时，你可令本回合点数为任意颜色的7（不投掷），至多发动三次。") }),
            new GeneralDefinition("tk-g22","孙权","吴王六剑","吴","### 22．孙权｜吴王六剑（吴）\n\n**制衡**\n\n出牌阶段你可以选择一项：\n\n1. 弃置最多四张手牌，然后摸相同数量的随机资源牌。\n2. 弃置一张发展牌，摸一张相同类型的发展牌。\n   每回合每个选项限一次。","2805c324c9e1f47bbc797805cca5e5ba576f5027d57dd273c1c2acaa64158df2",new[] { new SkillDefinition("tk-g22-s1","制衡","出牌阶段你可以选择一项：\n\n1. 弃置最多四张手牌，然后摸相同数量的随机资源牌。\n2. 弃置一张发展牌，摸一张相同类型的发展牌。\n   每回合每个选项限一次。") }),
            new GeneralDefinition("tk-g23","陆逊","烈火烛天","吴","### 23．陆逊｜烈火烛天（吴）\n\n**连营**\n\n当你失去最后一张手牌时，摸一张任意资源牌和一张随机资源牌。\n\n**谦逊**\n\n每个玩家的出牌阶段你都可以弃置你一张手牌。你不可成为间谍/大商家/乐不思蜀/顺手牵羊的目标。","90e91c53d1c5df3cb26f20fd62f03acd025f0cb7ca1fb5b67cf8aaa37e19970f",new[] { new SkillDefinition("tk-g23-s1","连营","当你失去最后一张手牌时，摸一张任意资源牌和一张随机资源牌。"),new SkillDefinition("tk-g23-s2","谦逊","每个玩家的出牌阶段你都可以弃置你一张手牌。你不可成为间谍/大商家/乐不思蜀/顺手牵羊的目标。") }),
            new GeneralDefinition("tk-g24","华雄","梦回唐朝","群","### 24．华雄｜梦回唐朝（群）\n\n**耀武**\n\n限定技，出牌阶段，你令本局游戏你的手牌上限+4，发展牌上限+2，当你的牌数/地块/建筑受到其他玩家的发展牌影响时，若此发展牌为蓝色，该玩家摸1张随机资源牌，若不为蓝色，你摸1张任意资源牌。华雄隐退后放置在你面前不进入轮换将池。\n\n**扬威**\n\n你的骑士始终视为激活状态，且可以无视等级驱赶任何玩家的骑士，隐退后失效。","25544936a02158cdba90c2282332ebfc7cec2d7b567038285f3798c1a87346fe",new[] { new SkillDefinition("tk-g24-s1","耀武","限定技，出牌阶段，你令本局游戏你的手牌上限+4，发展牌上限+2，当你的牌数/地块/建筑受到其他玩家的发展牌影响时，若此发展牌为蓝色，该玩家摸1张随机资源牌，若不为蓝色，你摸1张任意资源牌。华雄隐退后放置在你面前不进入轮换将池。"),new SkillDefinition("tk-g24-s2","扬威","你的骑士始终视为激活状态，且可以无视等级驱赶任何玩家的骑士，隐退后失效。") }),
            new GeneralDefinition("tk-g25","董卓","乱世魔王","群","### 25．董卓｜乱世魔王（群）\n\n**崩坏**\n\n你的回合结束时，若你的分数不为唯一最高，你可以拆除/横置一名玩家一条道路。\n\n**横征**\n\n你的回合内，你没有摸牌阶段。在其他玩家的摸牌阶段开始时，若你的手牌数或分数为唯一最少，你可以放弃摸牌并获得每名玩家各一张手牌。","87eb3b91d1bc5c8af86297cf60f8f0a7425057b15502ac981894161cbd2701be",new[] { new SkillDefinition("tk-g25-s1","崩坏","你的回合结束时，若你的分数不为唯一最高，你可以拆除/横置一名玩家一条道路。"),new SkillDefinition("tk-g25-s2","横征","你的回合内，你没有摸牌阶段。在其他玩家的摸牌阶段开始时，若你的手牌数或分数为唯一最少，你可以放弃摸牌并获得每名玩家各一张手牌。") }),
            new GeneralDefinition("tk-g26","阚泽","循循善诱","吴","### 26．阚泽｜循循善诱（吴）\n\n**下书**\n\n出牌阶段限一次，你可以将所有手牌交给一名其他玩家，然后该玩家亮出任意数量的手牌，令你选择一项：1.获得其亮出的手牌。2.获得其未亮出的手牌。\n\n**宽释**\n\n在其他玩家回合内，当你失去第二张手牌或获得第二张手牌时，你摸一张任意资源牌。","7928cd4da72cb5374650f64b1a100ae861de76d785c8fa7b8fc79e079c46d6ad",new[] { new SkillDefinition("tk-g26-s1","下书","出牌阶段限一次，你可以将所有手牌交给一名其他玩家，然后该玩家亮出任意数量的手牌，令你选择一项：1.获得其亮出的手牌。2.获得其未亮出的手牌。"),new SkillDefinition("tk-g26-s2","宽释","在其他玩家回合内，当你失去第二张手牌或获得第二张手牌时，你摸一张任意资源牌。") }),
            new GeneralDefinition("tk-g27","孙尚香","前后两难","吴","### 27．孙尚香｜前后两难（吴）\n\n**结姻**\n\n登场时，你立即与一名玩家结婚，当该玩家建造建筑时，你可以免费修建相同的建筑，当该玩家失去手牌时，你弃置相同数量的手牌。\n\n**枭姬**\n\n当你失去发展牌时，你摸三张任意资源牌，每回合限一次。","8d7317913718c1b445aec581c25b3cf3a1dd1df25b27db14b34487093c91df0d",new[] { new SkillDefinition("tk-g27-s1","结姻","登场时，你立即与一名玩家结婚，当该玩家建造建筑时，你可以免费修建相同的建筑，当该玩家失去手牌时，你弃置相同数量的手牌。"),new SkillDefinition("tk-g27-s2","枭姬","当你失去发展牌时，你摸三张任意资源牌，每回合限一次。") }),
            new GeneralDefinition("tk-g28","吕蒙","剑起惊澜","吴","### 28．吕蒙｜剑起惊澜（吴）\n\n**涉猎**\n\n摸牌阶段，你可以放弃摸牌然后亮出四张随机资源牌，然后获得不同的牌至多三张。\n\n**克己**\n\n任意玩家的回合结束时，若你本回合未失去过手牌，你摸一张随机资源牌，且下个回合内你不会被动失去牌。","edcd1568b5e540bae5fef3a6ba105f2083b991642c9e2d0c08df06d8c6bc67c0",new[] { new SkillDefinition("tk-g28-s1","涉猎","摸牌阶段，你可以放弃摸牌然后亮出四张随机资源牌，然后获得不同的牌至多三张。"),new SkillDefinition("tk-g28-s2","克己","任意玩家的回合结束时，若你本回合未失去过手牌，你摸一张随机资源牌，且下个回合内你不会被动失去牌。") }),
            new GeneralDefinition("tk-g29","曹丕","气荡山河","魏","### 29．曹丕｜气荡山河（魏）\n\n**放逐**\n\n限定技，你令两名玩家翻面。\n\n**颂威**\n\n每次点数为7的弃牌结算后，你摸一张任意资源牌/商品牌。","fd7d1f2d175cb769ebe3a0f06ef30b7d63465b1e6c960f3d1fc42f5f63b40a2a",new[] { new SkillDefinition("tk-g29-s1","放逐","限定技，你令两名玩家翻面。"),new SkillDefinition("tk-g29-s2","颂威","每次点数为7的弃牌结算后，你摸一张任意资源牌/商品牌。") }),
            new GeneralDefinition("tk-g30","曹植","龙生九子","魏","### 30．曹植｜龙生九子（魏）\n\n**落英**\n\n你的回合外，你可以获得一张其他玩家打出或弃置的木头，每回合每名玩家限两张。\n\n**酒诗**\n\n出牌阶段限一次，你可以翻面获得三张任意资源牌。你的回合外限三次，若你已翻面，你可以在其他玩家回合结束时，弃置七张木头执行你的一个额外回合。","228b172348423dcfb9eabdbda75a4787560d779fccc93aa3d742466ea655fd05",new[] { new SkillDefinition("tk-g30-s1","落英","你的回合外，你可以获得一张其他玩家打出或弃置的木头，每回合每名玩家限两张。"),new SkillDefinition("tk-g30-s2","酒诗","出牌阶段限一次，你可以翻面获得三张任意资源牌。你的回合外限三次，若你已翻面，你可以在其他玩家回合结束时，弃置七张木头执行你的一个额外回合。") }),
            new GeneralDefinition("tk-g31","李儒","鸠杀少帝","群","### 31．李儒｜鸠杀少帝（群）\n\n**焚城**\n\n限定技，你选择任意玩家为起点，从该玩家开始每名玩家选择弃置比上家数量更多的牌（至少为1）或者拆除两条道路，若二者都不选则焚毁一座城市\n\n**绝策**\n\n回合结束时，你可以令没有手牌的所有玩家拆除一条道路或弃置一张发展牌。","7fb41bd3ba61f128d6195e347bdfba25154aca481926aff578554060af040934",new[] { new SkillDefinition("tk-g31-s1","焚城","限定技，你选择任意玩家为起点，从该玩家开始每名玩家选择弃置比上家数量更多的牌（至少为1）或者拆除两条道路，若二者都不选则焚毁一座城市"),new SkillDefinition("tk-g31-s2","绝策","回合结束时，你可以令没有手牌的所有玩家拆除一条道路或弃置一张发展牌。") }),
            new GeneralDefinition("tk-g32","徐盛","大宝","吴","### 32．徐盛｜大宝（吴）\n\n**破军**\n\n你对任意玩家使用发展牌时，你可以扣置对方至多x级设施（x为对方拥有的牌数），被扣置的设施失去相应效果。若拥有大都会的设施因此小于4级，则失去大都会。玩家出牌阶段开始时，恢复所有被扣置的设施。三种设施等级数均不大于你的玩家受到你的发展牌效果翻倍\n\n**疑城**\n\n限定技，出牌阶段，你可以弃置两张手牌视为打出一张“主教”。","1740654c49912e33c0713890bc12cdbb59564144f1d69fdda7843fdde2d9c296",new[] { new SkillDefinition("tk-g32-s1","破军","你对任意玩家使用发展牌时，你可以扣置对方至多x级设施（x为对方拥有的牌数），被扣置的设施失去相应效果。若拥有大都会的设施因此小于4级，则失去大都会。玩家出牌阶段开始时，恢复所有被扣置的设施。三种设施等级数均不大于你的玩家受到你的发展牌效果翻倍"),new SkillDefinition("tk-g32-s2","疑城","限定技，出牌阶段，你可以弃置两张手牌视为打出一张“主教”。") }),
            new GeneralDefinition("tk-g33","黄月英","明良千古","蜀","### 33．黄月英｜明良千古（蜀）\n\n**集智**\n\n每次骰子被投掷后，若不为海盗入侵且你未获得发展牌，你摸一张任意资源牌。当你打出发展牌后，你摸一张随机资源牌。\n\n**奇才**\n\n你的发展牌没有上限和使用限制。","f469840825fd02f28ec9527e25b633c1ee42a7b9146227eaf8796119da91a3ec",new[] { new SkillDefinition("tk-g33-s1","集智","每次骰子被投掷后，若不为海盗入侵且你未获得发展牌，你摸一张任意资源牌。当你打出发展牌后，你摸一张随机资源牌。"),new SkillDefinition("tk-g33-s2","奇才","你的发展牌没有上限和使用限制。") }),
            new GeneralDefinition("tk-g34","荀攸","竹风韵凉","魏","### 34．荀攸｜竹风韵凉（魏）\n\n**奇策**\n\n回合开始时，你可以弃置所有手牌视为打出一张任意发展牌（不包括1分牌）。\n\n**智愚**\n\n你的回合外，当有玩家打出发展牌时，你可以摸一张随机资源并展示所有手牌，若都相同，则该玩家弃置一张手牌。","b43b86ed79eedcc80f27b694c46a48661d1cd0d37cb918b383d879d288b59a93",new[] { new SkillDefinition("tk-g34-s1","奇策","回合开始时，你可以弃置所有手牌视为打出一张任意发展牌（不包括1分牌）。"),new SkillDefinition("tk-g34-s2","智愚","你的回合外，当有玩家打出发展牌时，你可以摸一张随机资源并展示所有手牌，若都相同，则该玩家弃置一张手牌。") }),
            new GeneralDefinition("tk-g35","庞统","龙跃凤鸣","蜀","### 35．庞统｜龙跃凤鸣（蜀）\n\n**连环**\n\n你可以弃置任意张石头，摸取等量的随机资源牌，无次数限制。\n\n**涅槃**\n\n限定技，出牌阶段开始时，若你为分数最低的玩家之一，你可以弃置所有手牌和发展牌并失去两个科技中的最高级设施，然后获得1分。庞统隐退后放置在你面前不进入轮换将池。","569eee1ae37376bb003a66f3aac6272a7c7a2c760bccc0526ec9a3ea626f427f",new[] { new SkillDefinition("tk-g35-s1","连环","你可以弃置任意张石头，摸取等量的随机资源牌，无次数限制。"),new SkillDefinition("tk-g35-s2","涅槃","限定技，出牌阶段开始时，若你为分数最低的玩家之一，你可以弃置所有手牌和发展牌并失去两个科技中的最高级设施，然后获得1分。庞统隐退后放置在你面前不进入轮换将池。") }),
            new GeneralDefinition("tk-g36","戏志才","举棋若定","魏","### 36．戏志才｜举棋若定（魏）\n\n**先辅**\n\n登场时，你选择一名玩家，每当其建造等级为x的设施/骑士后，你也可以免费建造等级之和至多为x的任意设施/骑士。\n\n**筹策**\n\n当你成为技能/发展牌的目标时，你弃置任意玩家一张手牌，若是先辅玩家，则为两张。","58d009686f6947b0adfe01a602084cefbf22301e739c64e6ef6592d26531471a",new[] { new SkillDefinition("tk-g36-s1","先辅","登场时，你选择一名玩家，每当其建造等级为x的设施/骑士后，你也可以免费建造等级之和至多为x的任意设施/骑士。"),new SkillDefinition("tk-g36-s2","筹策","当你成为技能/发展牌的目标时，你弃置任意玩家一张手牌，若是先辅玩家，则为两张。") }),
            new GeneralDefinition("tk-g37","郭嘉","一世风华","魏","### 37．郭嘉｜一世风华（魏）\n\n**天妒**\n\n任意玩家的摸牌阶段，你可以改为分别摸你的两个地块能产出的一张资源牌/商品牌，这两个地块点数之和需等于骰子点数之和。\n\n**遗计**\n\n你成为其他玩家技能或发展牌的目标后，你摸一张任意资源牌。","b4e6741b9b0cdd606b71daf190ed7a294243217c68da27267f29a2096e590de2",new[] { new SkillDefinition("tk-g37-s1","天妒","任意玩家的摸牌阶段，你可以改为分别摸你的两个地块能产出的一张资源牌/商品牌，这两个地块点数之和需等于骰子点数之和。"),new SkillDefinition("tk-g37-s2","遗计","你成为其他玩家技能或发展牌的目标后，你摸一张任意资源牌。") }),
            new GeneralDefinition("tk-g38","张飞","据水断桥","蜀","### 38．张飞｜据水断桥（蜀）\n\n**咆哮**\n\n任何玩家新建的建筑不可以与你的建筑相连接。\n\n**替身**\n\n任意回合的摸牌阶段开始时，你可以将手牌随机摸至你上回合开始时的手牌数量（至多为7）。","8d19b783a1ebae4442354db0020a02a092c3233700fe13ee95b31c730201b402",new[] { new SkillDefinition("tk-g38-s1","咆哮","任何玩家新建的建筑不可以与你的建筑相连接。"),new SkillDefinition("tk-g38-s2","替身","任意回合的摸牌阶段开始时，你可以将手牌随机摸至你上回合开始时的手牌数量（至多为7）。") }),
            new GeneralDefinition("tk-g39","荀彧","驱虎吞狼","魏","### 39．荀彧｜驱虎吞狼（魏）\n\n**驱虎**\n\n你声明任意数量手牌中的小麦数量，令一名玩家猜测是否正确，然后展示之，若你赢，该玩家弃置左右两边玩家各一张手牌，若你没赢，该玩家弃置你两张手牌。\n\n**节命**\n\n限定技，出牌阶段，你可将手牌摸至手牌上限。摸牌时，一半为任意资源牌（向下取整），一半为随机资源牌。","c1a614081ecd3bf3303c1a6650dc966e8aa2b4a081f3c5397750e59a70e86f87",new[] { new SkillDefinition("tk-g39-s1","驱虎","你声明任意数量手牌中的小麦数量，令一名玩家猜测是否正确，然后展示之，若你赢，该玩家弃置左右两边玩家各一张手牌，若你没赢，该玩家弃置你两张手牌。"),new SkillDefinition("tk-g39-s2","节命","限定技，出牌阶段，你可将手牌摸至手牌上限。摸牌时，一半为任意资源牌（向下取整），一半为随机资源牌。") }),
            new GeneralDefinition("tk-g40","蒋干","虚义伪诚","魏","### 40．蒋干｜虚义伪诚（魏）\n\n**盗书**\n\n出牌阶段限一次，你可以选择一种资源/商品牌，然后抽取一名玩家一张手牌，若该牌与你所选相同，该技能视为未发动。你于回合内获得其他玩家的手牌后，若你的手牌数量少于4，你摸一张随机资源牌。","6287ae342f59f90345b924d7f8f5ab8e8918807f3bce51dfa8c5bce187684206",new[] { new SkillDefinition("tk-g40-s1","盗书","出牌阶段限一次，你可以选择一种资源/商品牌，然后抽取一名玩家一张手牌，若该牌与你所选相同，该技能视为未发动。你于回合内获得其他玩家的手牌后，若你的手牌数量少于4，你摸一张随机资源牌。") }),
            new GeneralDefinition("tk-g41","杜预","弼朝博虬","群","### 41．杜预｜弼朝博虬（群）\n\n**武库**\n\n场上有建筑被建造后，你获得1枚“武库”标记（至多为3）。\n\n**三陈**\n\n任意玩家的回合结束时，若你已有3枚“武库”标记，你失去“三陈”，然后获得技能“灭吴”。\n\n**灭吴**\n\n每个回合限一次，你可以弃1枚“武库”标记，合法执行一项，然后摸一张随机资源牌。\n\n1. 弃1枚”武库“标记将一张手牌当作任意一张资源牌/商品牌打出或交易。\n2. 弃3枚”武库“标记将一张手牌当作任意发展牌（不包括1分牌）打出。","a365fd0be31578930f303e89c155b18f0c813c1787b7f0f202eeb61cbd48f333",new[] { new SkillDefinition("tk-g41-s1","武库","场上有建筑被建造后，你获得1枚“武库”标记（至多为3）。"),new SkillDefinition("tk-g41-s2","三陈","任意玩家的回合结束时，若你已有3枚“武库”标记，你失去“三陈”，然后获得技能“灭吴”。"),new SkillDefinition("tk-g41-s3","灭吴","每个回合限一次，你可以弃1枚“武库”标记，合法执行一项，然后摸一张随机资源牌。\n\n1. 弃1枚”武库“标记将一张手牌当作任意一张资源牌/商品牌打出或交易。\n2. 弃3枚”武库“标记将一张手牌当作任意发展牌（不包括1分牌）打出。") }),
            new GeneralDefinition("tk-g42","赵云","截江救主","蜀","### 42．赵云｜截江救主（蜀）\n\n**龙胆**\n\n你在任何时机可以将你的砖视作木头，木头视作砖，麦子视作羊，羊视作麦子。\n\n**涯角**\n\n你每于回合外失去一张手牌时，你都可以摸一张随机资源牌/商品牌，若此牌与你失去的牌相同，则你获得之。","0c290472b262b978483f5bcaf5aa12b5f5bf836b59537246ea2475914cee08da",new[] { new SkillDefinition("tk-g42-s1","龙胆","你在任何时机可以将你的砖视作木头，木头视作砖，麦子视作羊，羊视作麦子。"),new SkillDefinition("tk-g42-s2","涯角","你每于回合外失去一张手牌时，你都可以摸一张随机资源牌/商品牌，若此牌与你失去的牌相同，则你获得之。") }),
            new GeneralDefinition("tk-g43","骆统","阊门治玉","吴","### 43．骆统｜阊门治玉（吴）\n\n**勤政**\n\n每当骰子点数为3/5/6/8/10/12时，你按顺序循环摸一张随机资源牌/资源牌/商品牌/资源牌/发展牌。","580e18464c7451d76e9e67b4f69d6909a1573779d8dd900443fb308b490a9bdb",new[] { new SkillDefinition("tk-g43-s1","勤政","每当骰子点数为3/5/6/8/10/12时，你按顺序循环摸一张随机资源牌/资源牌/商品牌/资源牌/发展牌。") }),
            new GeneralDefinition("tk-g44","甄姬","洛水神韵","魏","### 44．甄姬｜洛水神韵（魏）\n\n**洛神**\n\n投掷阶段，若点数为奇数，你摸一张随机资源牌，然后你可以再次投掷，最后一次投掷结果为最终点数。\n\n**倾国**\n\n你可以将商品牌当作对应资源牌使用。","57d45c1fe51f79290a6e4bb9859243e4ebaa5df77ff6f37d05094f6d617385b2",new[] { new SkillDefinition("tk-g44-s1","洛神","投掷阶段，若点数为奇数，你摸一张随机资源牌，然后你可以再次投掷，最后一次投掷结果为最终点数。"),new SkillDefinition("tk-g44-s2","倾国","你可以将商品牌当作对应资源牌使用。") }),
            new GeneralDefinition("tk-g45","刘琦","避走江南","蜀","### 45．刘琦｜避走江南（蜀）\n\n**问计**\n\n出牌阶段，你可以令一名其他玩家交给你一张手牌，你手牌中与之相同的牌视为问计牌，问计牌可以进行2：1贸易。\n\n**屯江**\n\n回合结束时，若本回合你未失去过牌，你摸x张随机资源牌（x为手牌中问计牌数）。","4cb507492593a03192218d3b8e65be7ad1da3eb78369e0efc01c8e4f63d89d07",new[] { new SkillDefinition("tk-g45-s1","问计","出牌阶段，你可以令一名其他玩家交给你一张手牌，你手牌中与之相同的牌视为问计牌，问计牌可以进行2：1贸易。"),new SkillDefinition("tk-g45-s2","屯江","回合结束时，若本回合你未失去过牌，你摸x张随机资源牌（x为手牌中问计牌数）。") }),
            new GeneralDefinition("tk-g46","麹义","沙场舞刀","群","### 46．麹义｜沙场舞刀（群）\n\n**伏骑**\n\n出牌阶段，与你领土接壤（具有共有地块或建筑互相连接）的玩家不能拒绝你发起的1：1和1：2交易，若该玩家没有符合数量的资源/商品，则交易失败。不论成功与否，你对领土接壤玩家至多能发起两次该比例交易。\n\n**骄姿**\n\n若你的手牌数为全场唯一最多，则你建造花费资源+1，若为全场唯一最少，则你建造花费资源-1（至少为1）。","06624702f0a4df015ddcc18189b1fd977959b2f78380d06938f923be2a626d3c",new[] { new SkillDefinition("tk-g46-s1","伏骑","出牌阶段，与你领土接壤（具有共有地块或建筑互相连接）的玩家不能拒绝你发起的1：1和1：2交易，若该玩家没有符合数量的资源/商品，则交易失败。不论成功与否，你对领土接壤玩家至多能发起两次该比例交易。"),new SkillDefinition("tk-g46-s2","骄姿","若你的手牌数为全场唯一最多，则你建造花费资源+1，若为全场唯一最少，则你建造花费资源-1（至少为1）。") }),
            new GeneralDefinition("tk-g47","鲁肃","众人之表","吴","### 47．鲁肃｜众人之表（吴）\n\n**榻谟**\n\n限定技，出牌阶段，你可以交换两个除金矿外的地图板块。若板块点数不为6/8则可交换成海洋沙漠板块，且点数一起被交换。\n\n**智盟**\n\n回合结束时，你可以选择一名其他玩家，你与其随机平均分配双方手牌，若为奇数，你获得较多数量的牌。\n\n**榻谟：板块交换说明**\n\n注：板块交换时，所有孤立建筑和骑士都随着板块一起平移，若平移后建筑不符合摆放规则，则板块顺时针旋转直至所有建筑都符合摆放规则，否则不可交换。港口所在板块被交换成海洋板块时，港口重新生成在离原位置最近的陆地版块上。岛屿板块若被换成了海洋，则原板块不计算登岛分。","e7fd12abab7e43e5d2f0e3e425c494722b851319c7399d9f08fc2ac2d183c160",new[] { new SkillDefinition("tk-g47-s1","榻谟","限定技，出牌阶段，你可以交换两个除金矿外的地图板块。若板块点数不为6/8则可交换成海洋沙漠板块，且点数一起被交换。"),new SkillDefinition("tk-g47-s2","智盟","回合结束时，你可以选择一名其他玩家，你与其随机平均分配双方手牌，若为奇数，你获得较多数量的牌。") }),
            new GeneralDefinition("tk-g48","司马师","剑戟淼淼","魏","### 48．司马师｜剑戟淼淼（魏）\n\n**败移**\n\n限定技，出牌阶段，你可以交换任意两名玩家的座次。\n\n**景略**\n\n出牌阶段限一次，你查看一名其他玩家的手牌并获取其中一张，然后除你外的玩家不能以任何方式获得该资源/商品直到你的下个回合开始。你每次选择的牌需与上一次不同。","fab2f8be4e6302f5e8cbf295f50b6989e99b3009f4b1b9417d80e34a0eb5bbc5",new[] { new SkillDefinition("tk-g48-s1","败移","限定技，出牌阶段，你可以交换任意两名玩家的座次。"),new SkillDefinition("tk-g48-s2","景略","出牌阶段限一次，你查看一名其他玩家的手牌并获取其中一张，然后除你外的玩家不能以任何方式获得该资源/商品直到你的下个回合开始。你每次选择的牌需与上一次不同。") }),
            new GeneralDefinition("tk-g49","邓艾","夜袭洮城","魏","### 49．邓艾｜夜袭洮城（魏）\n\n**屯田**\n\n当你于回合外失去手牌时，你投掷一次骰子，若点数大于5则你获得1个田标记（数量至多为3，初始为2）。\n\n**急袭**\n\n田标记可被视为顺手牵羊打出。\n顺手牵羊：获得对方一张手牌。","0e75aafd2f8146dee17dd0df6ba4554a1813dd5d5941ffa612f9fa88d337a501",new[] { new SkillDefinition("tk-g49-s1","屯田","当你于回合外失去手牌时，你投掷一次骰子，若点数大于5则你获得1个田标记（数量至多为3，初始为2）。"),new SkillDefinition("tk-g49-s2","急袭","田标记可被视为顺手牵羊打出。\n顺手牵羊：获得对方一张手牌。") }),
            new GeneralDefinition("tk-g50","钟会","潜蛟觊天","魏","### 50．钟会｜潜蛟觊天（魏）\n\n**自立**\n\n登场时，所有玩家依次选择一项:\n\n1. 成为你的盟友（你可以拒绝或者有条件同意）。\n2. 向你宣战成为你的敌人。\n   盟友之间共享港口、科技树、骑士，不可互相攻伐，共同胜利，你至多拥有一半人数（向下取整）的盟友，不同阵营之间的玩家不可进行交易。\n\n**排异**\n\n登场时，你获得一张蓝色和黄色发展牌。你对所有敌人使用发展牌时对方受的效果翻倍。","3c1fa9fd963d2f6c8635891e09bdb3ee956492df7a42eb34f917e5f60a46d5a0",new[] { new SkillDefinition("tk-g50-s1","自立","登场时，所有玩家依次选择一项:\n\n1. 成为你的盟友（你可以拒绝或者有条件同意）。\n2. 向你宣战成为你的敌人。\n   盟友之间共享港口、科技树、骑士，不可互相攻伐，共同胜利，你至多拥有一半人数（向下取整）的盟友，不同阵营之间的玩家不可进行交易。"),new SkillDefinition("tk-g50-s2","排异","登场时，你获得一张蓝色和黄色发展牌。你对所有敌人使用发展牌时对方受的效果翻倍。") }),
            new GeneralDefinition("tk-g51","黄忠","明良千古","蜀","### 51．黄忠｜明良千古（蜀）\n\n**烈弓**\n\n记录你于出牌阶段打出的每一张牌，若不同的牌数量不小于7，则你于出牌阶段可以摧毁场上任何一个建筑，若为道路，则改为两条，然后重新记录。\n\n**黄忠专属摧毁规则**\n\n摧毁规则：大都会转移至另一个城市，若没有其他城市，则该城市不可被摧毁；城市倒塌为村庄；村庄倒塌则不可收取任何资源，且不计分；骑士直接死亡；开放道路直接失去，封闭道路则横置；任何倒塌/横置的建筑都必须被优先修复，否则不可建造同类建筑。","94162187d9e0c7ff659bb5ef922a11eb5c413741b7351e3974bab601da746192",new[] { new SkillDefinition("tk-g51-s1","烈弓","记录你于出牌阶段打出的每一张牌，若不同的牌数量不小于7，则你于出牌阶段可以摧毁场上任何一个建筑，若为道路，则改为两条，然后重新记录。") }),
            new GeneralDefinition("tk-g52","马良","挥毫自荐","蜀","### 52．马良｜挥毫自荐（蜀）\n\n**自书**\n\n你的回合内，当你不因此技能效果获得手牌时，摸一张随机资源牌。\n\n**协穆**\n\n出牌阶段限一次，你可以弃置一张黄色发展牌和一张任意发展牌视作打出垄断资源/商品。","4a23df7f409e284409f5d1628998dc35ebd6555a6e2893ba2cdc14eccad5f119",new[] { new SkillDefinition("tk-g52-s1","自书","你的回合内，当你不因此技能效果获得手牌时，摸一张随机资源牌。"),new SkillDefinition("tk-g52-s2","协穆","出牌阶段限一次，你可以弃置一张黄色发展牌和一张任意发展牌视作打出垄断资源/商品。") }),
            new GeneralDefinition("tk-g53","周处","义除三害","吴","### 53．周处｜义除三害（吴）\n\n**乡害**\n\n锁定技，你的投掷点数始终+3，其他玩家的手牌上限-1，其他玩家建造村庄/城市/骑士后需交给你一张手牌，若你以此法获得了不小于两张手牌，你获得技能除害。\n\n**除害**\n\n出牌阶段限一次，你选择一名手牌数不为唯一最少的玩家与之掷骰子比大小，若你赢，你查看其手牌并弃置其中一张，然后你获得其手牌中没有的资源/商品牌各一张，若你没赢，则你明牌直至你下个回合开始。","5b1b85ba05f6e59beb1d1d429ea1ad0f1e432c632632f5c391c04235ab018a71",new[] { new SkillDefinition("tk-g53-s1","乡害","锁定技，你的投掷点数始终+3，其他玩家的手牌上限-1，其他玩家建造村庄/城市/骑士后需交给你一张手牌，若你以此法获得了不小于两张手牌，你获得技能除害。"),new SkillDefinition("tk-g53-s2","除害","出牌阶段限一次，你选择一名手牌数不为唯一最少的玩家与之掷骰子比大小，若你赢，你查看其手牌并弃置其中一张，然后你获得其手牌中没有的资源/商品牌各一张，若你没赢，则你明牌直至你下个回合开始。") }),
            new GeneralDefinition("tk-g54","华佗","鹿林圣手","群","### 54．华佗｜鹿林圣手（群）\n\n**青囊**\n\n出牌阶段，你可以弃置一张手牌修复场上任意一个建筑，若该手牌该建筑所需资源之一，则你可以再次发动。若该建筑为你的，则你摸一张任意资源牌/商品牌。\n\n**除痂**\n\n限定技，本局游戏内，你的村庄/城市不会倒塌。","46bc725a143e2dd5a746db46867f55a0d88529c8dcc772d3b2e8923cfe11f37c",new[] { new SkillDefinition("tk-g54-s1","青囊","出牌阶段，你可以弃置一张手牌修复场上任意一个建筑，若该手牌该建筑所需资源之一，则你可以再次发动。若该建筑为你的，则你摸一张任意资源牌/商品牌。"),new SkillDefinition("tk-g54-s2","除痂","限定技，本局游戏内，你的村庄/城市不会倒塌。") }),
        };
        public static GeneralDefinition[] Definitions => (GeneralDefinition[])items.Clone();
        public static GeneralDefinition[] EnabledDefinitions => items.Where(g => IsEnabled(g.Id)).ToArray();
        public static GeneralDefinition[] B2Definitions => items.Where(g => IsB2Enabled(g.Id)).ToArray();
        public static GeneralDefinition[] B4Definitions => items.Where(g => IsB4Enabled(g.Id)).ToArray();
        public static string B4ContentHash { get; } = Json.Hash(B4RulesVersion + "\n" + B4PackageVersion + "\n" + string.Join("\n", items.Where(g => IsB4Enabled(g.Id)).Select(x => x.Id + ":" + x.SourceHash + ":skills-enabled-b4-v1")));
        public static string B2ContentHash { get; } = Json.Hash(B2RulesVersion + "\n" + B2PackageVersion + "\n" + string.Join("\n", items.Where(g => IsB2Enabled(g.Id)).Select(x => x.Id + ":" + x.SourceHash + ":skills-enabled-b2-v1")));
        public static string B3ContentHash { get; } = Json.Hash(B3RulesVersion + "\n" + B3PackageVersion + "\n" + string.Join("\n", items.Where(g => IsEnabled(g.Id)).Select(x => x.Id + ":" + x.SourceHash + ":skills-enabled-b3-v1")));
        public static string ContentHash { get; } = Json.Hash(RulesVersion + "\n" + PackageVersion + "\n" + string.Join("\n", items.Select(x => x.Id + ":" + x.SourceHash + ":skills-disabled")));
        public static GeneralDefinition Get(string id) => items.FirstOrDefault(x => x.Id == id);
    }
}
